#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> a(2 * n);
    for (ll& x : a) cin >> x;
    sort(a.begin(), a.end());

    const ll INF = numeric_limits<ll>::max() / 4;
    ll dp[3][2], nextDp[3][2];

    fill(&dp[0][0], &dp[0][0] + 6, INF);
    dp[0][0] = 0;

    for (ll x : a) {
        fill(&nextDp[0][0], &nextDp[0][0] + 6, INF);

        for (int skipped = 0; skipped <= 2; ++skipped) {
            for (int pending = 0; pending <= 1; ++pending) {
                if (dp[skipped][pending] == INF) continue;

                if (skipped < 2) {
                    nextDp[skipped + 1][pending] =
                        min(nextDp[skipped + 1][pending],
                            dp[skipped][pending]);
                }

                if (pending == 0) {
                    nextDp[skipped][1] =
                        min(nextDp[skipped][1],
                            dp[skipped][0] - x);
                } else {
                    nextDp[skipped][0] =
                        min(nextDp[skipped][0],
                            dp[skipped][1] + x);
                }
            }
        }

        copy(&nextDp[0][0], &nextDp[0][0] + 6, &dp[0][0]);
    }

    cout << dp[2][0] << '\n';
    return 0;
}

