#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<ll> a(2 * n);
    for (ll& x : a) cin >> x;
    sort(a.begin(), a.end());

    const ll INF = numeric_limits<ll>::max() / 4;

    // dp[skipped][open]: minimum cost after processing a prefix.
    ll dp[3][2], nextDp[3][2];
    fill(&dp[0][0], &dp[0][0] + 6, INF);
    dp[0][0] = 0;

    for (ll x : a) {
        fill(&nextDp[0][0], &nextDp[0][0] + 6, INF);

        for (int skipped = 0; skipped <= 2; ++skipped) {
            for (int open = 0; open <= 1; ++open) {
                if (dp[skipped][open] == INF) continue;

                if (skipped < 2) {
                    nextDp[skipped + 1][open] =
                        min(nextDp[skipped + 1][open], dp[skipped][open]);
                }

                if (open == 0) {
                    nextDp[skipped][1] =
                        min(nextDp[skipped][1], dp[skipped][0] - x);
                } else {
                    nextDp[skipped][0] =
                        min(nextDp[skipped][0], dp[skipped][1] + x);
                }
            }
        }

        copy(&nextDp[0][0], &nextDp[0][0] + 6, &dp[0][0]);
    }

    cout << dp[2][0] << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    const int total = 2 * n;
    const int pairs = n - 1;

    vector<ll> a(total);
    for (ll& x : a) cin >> x;
    sort(a.begin(), a.end());

    const ll INF = numeric_limits<ll>::max() / 4;

    vector<ll> dp0(pairs + 1, INF);
    vector<ll> dp1(pairs + 1, INF);
    vector<ll> cur(pairs + 1, INF);

    dp0[0] = 0;

    if (total >= 1) {
        dp1[0] = 0;
    }

    for (int i = 2; i <= total; ++i) {
        fill(cur.begin(), cur.end(), INF);
        cur[0] = 0;

        for (int j = 1; j <= pairs; ++j) {
            cur[j] = dp1[j];

            if (dp0[j - 1] != INF) {
                cur[j] = min(cur[j],
                             dp0[j - 1] + a[i - 1] - a[i - 2]);
            }
        }

        dp0.swap(dp1);
        dp1.swap(cur);
    }

    cout << (total == 0 ? 0 : dp1[pairs]) << '\n';
    return 0;
}

